#!/usr/bin/env bash
# Run this on your OWN machine (not the Claude sandbox, which blocks the CDN host).
# Downloads all 87 scene images named by the timestamp they correspond to,
# e.g. 0:00.png ... 6:23.png, plus character.png, into ./images/.
set -uo pipefail
cd "$(dirname "$0")"
mkdir -p images
fail=0
dl(){ if curl -fSL --retry 4 -o "images/$1" "$2"; then echo "  ok  $1"; else echo "  FAIL $1"; fail=$((fail+1)); fi; }

dl "character.png" "https://d8j0ntlcm91z4.cloudfront.net/user_3EJ7eXPRDK8j3ZmKXW0B5KfoJTg/hf_20260614_230226_d701e36e-0b35-4752-8a16-2fa68810f3f5.png"
